51	function parseArgs(argv) {
52	  const options = { input: null, output: DEFAULT_OUTPUT, open: false, consumeInput: false };
53	
54	  for (let index = 0; index < argv.length; index += 1) {
55	    const argument = argv[index];
56	    if (argument === "--input") {
57	      options.input = argv[++index];
58	    } else if (argument === "--output") {
59	      options.output = argv[++index];
60	    } else if (argument === "--open") {
61	      options.open = true;
62	    } else if (argument === "--consume-input") {
63	      options.consumeInput = true;
